"""Detect a Negative Weight Cycle — Bellman-Ford with a virtual source.

Starting every node at distance 0 is equivalent to adding a source with a
zero-weight edge to each, so cycles in components that are unreachable from any
particular node are still detected.

Time: O(V * E)   Space: O(V)
"""
from typing import List


class Solution:
    def hasNegativeCycle(self, n: int, edges: List[List[int]]) -> bool:
        dist = [0] * n
        for _ in range(n - 1):
            changed = False
            for u, v, w in edges:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    changed = True
            if not changed:
                break
        return any(dist[u] + w < dist[v] for u, v, w in edges)
